        //    а потом разорви оба цикла

    }

    deinit {
        lifecycleLog.append("Экран освобождён: \(album.title)")
    }
}

// Сценарий из тикета
var album: Album? = Album(title: "Отпуск 2025")
var screen: AlbumScreen?
if let currentAlbum = album {
